    p_mekan_id: mekanId,
    p_lat: lat,
    p_lng: lng,
    p_not_metni: notMetni,
    p_fotograf: fotograf,
    p_bulunurluk: bulunurluk,
  })
  if (error) throw new Error(error.message)
  return satiriCheckInACevir(data as CheckInSatiri)
}

